python3 -c "
import importlib
for mod in ['pypdf', 'PyPDF2', 'fpdf', 'pdfplumber', 'fitz', 'reportlab', 'weasyprint']:
    try:
        importlib.import_module(mod)
        print(mod, 'OK')
    except Exception as e:
        print(mod, 'MISSING')
