python3 -c "
import os
print('report.pdf exists:', os.path.exists('report.pdf'))
for mod in ['pypdf', 'PyPDF2', 'fpdf', 'pdfplumber', 'fitz']:
    try:
        __import__(mod)
        print(mod, 'OK')
    except Exception:
        print(mod, 'MISSING')
"

python3 -c "
import os
from pypdf import PdfReader
for p in ['report.pdf', '../report.pdf', './report.pdf']:
    if os.path.exists(p):
        print('FOUND', os.path.abspath(p))
        break
else:
    print('NOT FOUND; cwd=', os.getcwd())
"

